transcripcion.texto:
```json
{
  "pasos": [
    {
      "id": "s1",
      "op": "search_catalog",
      "args": {
        "query": "audífonos",
        "category": "audifonos",
        "attributes": {
          "autonomia_horas": {"min": 24}
        },
        "limit": 5
      }
    },
    {
      "id": "s2",
      "op": "get_reviews",
      "args": {
        "product_id": "$s1.0.id",
        "limit": 3
      }
    },
    {
      "id": "s3",
      "op": "get_product",
      "args": {
        "id": "$s1.1.id"
      }
    },
    {
      "id": "s4",
      "op": "get_reviews",
      "args": {
        "product_id": "$s1.1.id",
        "limit": 3
      }
    },
    {
      "id": "s5",
      "op": "compare_products",
      "args": {
        "ids": ["$s1.0.id", "$s1.1.id"]
      }
    },
    {
      "id": "s6",
      "op": "respond",
      "plantilla": "Para tus viajes largos, te recomiendo estos audífonos con autonomía de al menos 24 horas:\n\n1. {nombre1} <<rec:{id1}>> - ${precio1:,} CLP. Evaluación: {rating1}/5. {resumen1}\n\n2. {nombre2} <<rec:{id2}>> - ${precio2:,} CLP. Evaluación: {rating2}/5. {resumen2}\n\nComparación <<cmp:{id1},{id2}>>: El más económico es {mas_barato}, mientras que {mejor_evaluado} tiene mejor evaluación de usuarios.",
      "vars": {
        "nombre1": "$s1.0.name",
        "id1": "$s1.0.id",
        "precio1": "$s1.0.price_clp",
        "rating1": "$s1.0.avg_rating",
        "resumen1": "$s2",
        "nombre2": "$s3.name",
        "id2": "$s3.id",
        "precio2": "$s3.price_clp",
        "rating2": "$s3.avg_rating",
        "resumen2": "$s4",
        "mas_barato": "$s5.mas_barato",
        "mejor_evaluado": "$s5.mejor_evaluado"
      }
    }
  ]
}
```
